import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;

public class FixedWidthRecordReaderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String read(String raw) {
        try {
            java.util.List<String> records = FixedWidthRecordReader.read(
                    new ByteArrayInputStream(raw.getBytes(StandardCharsets.US_ASCII)));
            return records == null ? "null" : records.toString();
        } catch (Exception e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        String bolt = "bolt      " + "  12";
        String washer = "washer    " + "0007";
        String hexKey = "hex key   " + "1234";
        String zero = "spacer    " + "   0";

        check("one record", "[bolt=12]", read(bolt));
        check("two records", "[bolt=12, washer=7]", read(bolt + washer));
        check("name with a space inside", "[hex key=1234]", read(hexKey));
        check("quantity of zero", "[spacer=0]", read(zero));
        check("order preserved", "[washer=7, bolt=12, spacer=0]", read(washer + bolt + zero));
        check("short trailing chunk ignored", "[bolt=12, washer=7]", read(bolt + washer + "extra"));
        check("empty stream", "[]", read(""));
        check("only a partial record", "[]", read("bolt  "));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

