import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

public class FixedWidthRecordReader {

    private static final int RECORD_SIZE = 14;
    private static final int NAME_SIZE = 10;

    public static List<String> read(InputStream in) throws IOException {
        List<String> records = new ArrayList<>();
        byte[] chunk = in.readNBytes(RECORD_SIZE);
        while (chunk.length == RECORD_SIZE) {
            String text = new String(chunk, StandardCharsets.US_ASCII);
            String name = text.substring(0, NAME_SIZE).trim();
            int quantity = Integer.parseInt(text.substring(NAME_SIZE).trim());
            records.add(name + "=" + quantity);
            chunk = in.readNBytes(RECORD_SIZE);
        }
        return records;
    }
}
